/* Curb ramp map for one street (any area page).  Data comes from data.js (window.RAMPS),
 * generated by scripts/build.rb. No build step for this file. */
"use strict";

// ------------------------------------------------------------------ config
const REPO = "olivierlacan/trebuche";          // where "log a filed request" issues go
const SDOT_FORM = "https://forms.office.com/g/R2d2GXDbXu";
const CSB_PORTAL = "https://seattle-cwiprod.motorolasolutions.com/";
const MAX_INTERSECTIONS_PER_FORM = 2;          // SDOT's rule for the ADA form
const CORNER_ZOOM = 20;

const DATA = window.RAMPS;
const AREA = DATA.area;                        // street, neighborhood, extent, id prefix
const MAIN_STREET = AREA.street;
const corners = DATA.corners;
const byId = new Map(corners.map(c => [c.corner_id, c]));
// Short IDs keep shared links readable: "dayton-61-NE" <-> "61-NE".
const PREFIX = `${AREA.id_prefix}-`;
const shortId = id => (id.startsWith(PREFIX) ? id.slice(PREFIX.length) : id);
const longId = id => (id.startsWith(PREFIX) ? id : PREFIX + id);
const selParam = ids => [...ids].map(shortId).join(",");

// ------------------------------------------------------------------ dates
const DAY = 864e5;
const now = new Date();
const today = now.getTime();
// Current week: Monday 00:00 to Sunday 23:59, viewer's local time.
const weekStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() - ((now.getDay() + 6) % 7)).getTime();
const weekEnd = weekStart + 7 * DAY - 1;
const parseDay = iso => (iso ? new Date(iso + "T00:00:00").getTime() : null);

// Install-date color: green for the last month, to yellow at one year, to
// brown at the oldest install in the data.
const GREEN = [26, 152, 80], YELLOW = [240, 200, 20], BROWN = [110, 62, 20];
const NO_DATE = "#c8c8c8";
const rgb = c => `rgb(${c.join(",")})`;
const mix = (a, b, t) => rgb(a.map((v, i) => Math.round(v + (b[i] - v) * Math.min(1, Math.max(0, t)))));
const oldest = DATA.city_ramps.map(r => r.installed).filter(Boolean).sort()[0];
const oldestAge = Math.max(730, (today - parseDay(oldest)) / DAY);

function ageColor(iso) {
  if (!iso) return NO_DATE;
  const age = (today - parseDay(iso)) / DAY;
  if (age <= 30) return rgb(GREEN);
  if (age <= 365) return mix(GREEN, YELLOW, (age - 30) / 335);
  return mix(YELLOW, BROWN, (age - 365) / (oldestAge - 365));
}
function ageText(iso) {
  if (!iso) return "install date not recorded";
  const days = Math.round((today - parseDay(iso)) / DAY);
  if (days < 60) return `installed ${iso} (${days} days ago)`;
  if (days < 730) return `installed ${iso} (${Math.round(days / 30.4)} months ago)`;
  return `installed ${iso} (${Math.round(days / 365.25)} years ago)`;
}

// ------------------------------------------------------------------ city work
// ongoing: the work order's date window overlaps this week, or it closed this week
// planned: still open otherwise (including ones past their estimated date)
function workState(w) {
  const start = parseDay(w.started), est = parseDay(w.est_complete), closed = parseDay(w.closed);
  if (closed) return closed >= weekStart && closed <= weekEnd ? "ongoing" : null;
  if (est && est >= weekStart && (!start || start <= weekEnd)) return "ongoing";
  return "planned";
}
function cornerWork(c) {
  const states = (c.work_orders || []).map(workState).filter(Boolean);
  return states.includes("ongoing") ? "ongoing" : states.includes("planned") ? "planned" : null;
}
function workText(w) {
  const st = workState(w);
  const what = w.kind === "resident request" ? "Resident curb ramp request" : "Planned construction";
  const proj = w.project ? ` (${w.project})` : "";
  let when = w.started ? `, opened ${w.started}` : "";
  if (w.est_complete) when += `, estimated done ${w.est_complete}` + (st === "planned" && parseDay(w.est_complete) < weekStart ? " (date has passed)" : "");
  if (w.closed) when += `, closed ${w.closed}`;
  return `${what}${proj}${when}`;
}

// ------------------------------------------------------------------ corner wording
const CORNER_WORDS = { NE: "northeast", NW: "northwest", SE: "southeast", SW: "southwest" };
const baseStreet = c => c.cross_street.replace(/\s*\(.*\)$/, "");
const kind = c => (c.confirmed_missing ? "x" : c.overall === "present" ? "ramp" : c.overall === "partial" ? "partial" : "q");
const crossingName = (c, k) => (k === "main" ? `crossing ${MAIN_STREET}` : `crossing ${baseStreet(c)}`);

function cornerTitle(c) {
  const jog = /\((west|east) side of jog\)/.exec(c.cross_street);
  const leg = /\(((?:west|east) leg)\)/.exec(c.cross_street); // side street that doesn't line up across
  return `${CORNER_WORDS[c.corner]} corner, ${MAIN_STREET} & ${baseStreet(c)}` +
    (jog ? ` (${jog[1]} half of the jog)` : leg ? ` (${leg[1]})` : "");
}
function statusLabel(c) {
  if (c.confirmed_missing) return ["missing", "No curb ramp"];
  if (c.overall === "missing") return ["unsure", "Probably no ramp (one source)"];
  if (c.overall === "partial") return ["partial", "Ramp for one crossing only"];
  if (c.overall === "present") return ["present", "Has curb ramps"];
  if (c.overall === "conflict") return ["unsure", "Not sure: sources disagree"];
  return ["unsure", "Not sure: no data"];
}
function needText(c) {
  const miss = (c.missing_crossings || "").split("+").filter(Boolean);
  if (!miss.length) return "";
  if (miss[0] === "unknown") return "One of the two crossings at this corner has no ramp (which one isn't clear from the data).";
  return `No ramp for ${miss.map(k => crossingName(c, k)).join(" or ")}.`;
}
// SDOT's "2023 PEMS DWW ramps on-hold" project, open since 2022: named from the work orders themselves.
function onHoldText(cs) {
  const wos = cs.flatMap(c => c.work_orders || []).filter(w => (w.project || "").includes("on-hold"));
  const names = [...new Set(wos.map(w => w.project))];
  const since = wos.map(w => w.started).filter(Boolean).sort()[0];
  return `SDOT's ${names.map(n => `"${n}"`).join(" and ")} project${names.length > 1 ? "s" : ""}` +
    (since ? `, open since ${since.slice(0, 4)}` : "");
}
const needsWork = c => c.overall === "missing" || c.overall === "partial";

// ------------------------------------------------------------------ in-person checks
// Neighbors can record what they see at a corner. Checks stay in this browser
// (localStorage, shared by every street's map) until they're sent as a GitHub
// issue and pasted into data/field-checks.csv, after which build.rb publishes them.
// A saved check redraws the corner for this visitor right away.
const CHECKS_KEY = "trebuche:checks";
const needsOf = c => (c.needs || "").split("+").filter(Boolean);
const coveredBy = rampsFor => (rampsFor === "none" ? [] : (rampsFor || "").split("+").filter(Boolean));
function loadChecks() {
  try { return JSON.parse(localStorage.getItem(CHECKS_KEY)) || {}; } catch { return {}; }
}
const checks = loadChecks();
function saveChecks() {
  try { localStorage.setItem(CHECKS_KEY, JSON.stringify(checks)); }
  catch { toast("This browser isn't saving checks (private browsing?). Send them before you close the page."); }
}
const ORIGINAL = new Map(corners.map(c => [c.corner_id, {
  overall: c.overall, confirmed_missing: c.confirmed_missing, missing_crossings: c.missing_crossings,
  sources_disagree: c.sources_disagree, note: c.note,
}]));
for (const k of Object.values(checks)) {
  if (k.pad === "no") k.issues = [...new Set([...(k.issues || "").split("+").filter(Boolean), "no_warning"])].join("+");
  delete k.pad;
}
// Once the published data has the same check (or a newer one), the local copy has done its job.
for (const c of corners) {
  const k = checks[c.corner_id];
  if (k && c.field_date && c.field_date >= k.date) delete checks[c.corner_id];
}
saveChecks();
const myChecks = () => corners.filter(c => checks[c.corner_id]);
function applyCheck(c) {
  Object.assign(c, ORIGINAL.get(c.corner_id));
  const k = checks[c.corner_id];
  if (!k) return;
  const gap = needsOf(c).filter(n => !coveredBy(k.ramps_for).includes(n));
  c.overall = !gap.length ? "present" : gap.length === needsOf(c).length ? "missing" : "partial";
  c.confirmed_missing = c.overall === "missing" ? "yes" : "";
  c.missing_crossings = gap.join("+");
  c.sources_disagree = "";
  c.note = "";
}
corners.forEach(applyCheck);
function checkText(c, rampsFor) {
  const covered = coveredBy(rampsFor);
  return needsOf(c).map(n => `${covered.includes(n) ? "ramp" : "no ramp"} ${crossingName(c, n)}`).join(", ");
}
// What's wrong with ramps that are there. Stored as "no_warning+old_style" (ramp_issues column).
// [checkbox label, words in sentences]
const RAMP_ISSUES = {
  diagonal: ["Central ramp facing the middle of the intersection", "one central ramp aimed at the middle of the intersection"],
  no_warning: ["No yellow pad", "no yellow pad"],
  old_style: ["Older crisscross style", "older crisscross style"],
  damaged: ["Cracked or uneven", "cracked or uneven"],
  lip: ["Lip at street edge", "lip at the street edge"],
};
const issueList = v => (v || "").split("+").filter(k => RAMP_ISSUES[k]);

// ------------------------------------------------------------------ report icons
// One small drawing per thing a report can say, in the logo's style: a curb ramp seen
// from above, the street below it. Fixed colors (concrete, asphalt, yellow pad) read the
// same in light and dark mode. Decorative: the label next to each says it in words.
const ICON = { walk: "#d6d4cf", ramp: "#bdbab3", edge: "#7d7a74", street: "#5b5f66", pad: "#f2c200", ink: "#2a2a2a" };
function rampPlan({ pad = true, outline = !pad, extra = "" } = {}) {
  const dots = pad ? [12, 16, 20].flatMap(x => [19.4, 21.4].map(y => `<circle cx="${x}" cy="${y}" r=".75" fill="#8a6d00"/>`)).join("") : "";
  return `<rect width="32" height="23" fill="${ICON.walk}"/><rect y="23" width="32" height="9" fill="${ICON.street}"/>
    <polygon points="4,23 10,8 22,8 28,23" fill="${ICON.ramp}" stroke="${ICON.edge}" stroke-width=".8"/>
    ${pad ? `<rect x="9.5" y="18" width="13" height="5" fill="${ICON.pad}" stroke="${ICON.edge}" stroke-width=".5"/>${dots}`
      : outline ? `<rect x="9.5" y="18" width="13" height="5" fill="none" stroke="${ICON.ink}" stroke-width=".9" stroke-dasharray="1.6 1.2"/>` : ""}
    ${extra}`;
}
function reportIcon(kind, c, n) {
  let body;
  if (kind === "ok") {
    body = rampPlan() + `<circle cx="25.5" cy="6.5" r="5.5" fill="#1a7f45" stroke="#fff" stroke-width="1.2"/>
      <path d="M22.8,6.6l1.9,1.9l3.6,-3.7" fill="none" stroke="#fff" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>`;
  } else if (kind === "miss") {
    // The street to cross (with its crosswalk) and the ✕ on this corner's curb. Drawn for
    // a street running across, the corner above or below it; turned a quarter clockwise
    // for the main street, which moves "above" to the right (east) and "below" to the left.
    const above = n === "cross" ? c.corner.startsWith("N") : c.corner.endsWith("E");
    const bars = [9, 13, 17, 21].map(x => `<rect x="${x}" y="11.5" width="2" height="9" fill="#fff" opacity=".85"/>`).join("");
    const curbY = above ? 10 : 22, xy = above ? 5.5 : 26.5;
    body = `<rect width="32" height="32" fill="${ICON.walk}"/><rect y="10" width="32" height="12" fill="${ICON.street}"/>${bars}
      <line x1="0" x2="32" y1="${curbY}" y2="${curbY}" stroke="${ICON.edge}" stroke-width="1.2"/>
      <path d="M12.5,${xy - 3.5}L19.5,${xy + 3.5}M19.5,${xy - 3.5}L12.5,${xy + 3.5}" stroke="#c0392b" stroke-width="2.4" stroke-linecap="round"/>`;
    if (n === "main") body = `<g transform="rotate(90 16 16)">${body}</g>`;
  } else if (kind === "diagonal") {
    // A corner from above (sidewalk in the corner's quarter, streets on the other two
    // sides, a crosswalk across each), with one ramp at the curve aimed at the middle of
    // the intersection, between the crosswalks. Drawn for NW, turned for the others.
    const turn = { NW: 0, NE: 90, SE: 180, SW: 270 }[c.corner] || 0;
    const bars = [19, 23, 27].map(x => `<rect x="${x}" y="2" width="2" height="10" fill="#fff" opacity=".85"/>`).join("") +
      [19, 23, 27].map(y => `<rect x="2" y="${y}" width="10" height="2" fill="#fff" opacity=".85"/>`).join("");
    body = `<g transform="rotate(${turn} 16 16)"><rect width="32" height="32" fill="${ICON.street}"/>${bars}
      <path d="M0,0H17V6A11,11 0 0 1 6,17H0Z" fill="${ICON.walk}" stroke="${ICON.edge}" stroke-width=".9"/>
      <path d="M9.3,8.3L16.6,8.85A11,11 0 0 1 8.85,16.6L8.3,9.3Z" fill="${ICON.ramp}" stroke="${ICON.edge}" stroke-width=".6"/>
      <path d="M14.26,8.67L16.6,8.85A11,11 0 0 1 8.85,16.6L8.67,14.26A8.7,8.7 0 0 0 14.26,8.67Z" fill="${ICON.pad}"/>
      <path d="M17.5,17.5L25,25" stroke="#c0392b" stroke-width="1.8" stroke-linecap="round" stroke-dasharray="2.4 2"/>
      <path d="M26.6,21.4V26.6H21.4" fill="none" stroke="#c0392b" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></g>`;
  } else if (kind === "no_warning") {
    body = rampPlan({ pad: false });
  } else if (kind === "old_style") {
    const lines = [-8, -3, 2, 7, 12, 17, 22].map(d => `<path d="M${4 + d},23L${19 + d},8M${4 + d},8L${19 + d},23" stroke="${ICON.edge}" stroke-width=".7"/>`).join("");
    body = `<defs><clipPath id="ramp-clip"><polygon points="4,23 10,8 22,8 28,23"/></clipPath></defs>` +
      rampPlan({ pad: false, outline: false, extra: `<g clip-path="url(#ramp-clip)">${lines}</g>` });
  } else if (kind === "damaged") {
    body = rampPlan({ extra: `<path d="M11.5,8.5l2.5,3l-2,2.5l4,2.5" fill="none" stroke="${ICON.ink}" stroke-width="1.4" stroke-linejoin="round"/>
      <path d="M19,9.5l1.5,3l2,1" fill="none" stroke="${ICON.ink}" stroke-width="1"/>` });
  } else if (kind === "lip") {
    // Elevation, cropped at the shins: someone walking up from the street, the front toe
    // stopped by the step where the ramp meets the gutter (red), the back heel lifting,
    // both legs pitching forward. Back leg and shoe lighter, for depth.
    const shoe = fill => `<path d="M11,0H2C.4,0 -.3,-1 0,-2.2C.4,-3.6 2.2,-4 4.2,-4.3L7.4,-5.2C8.4,-6.6 9.7,-7 11,-7Z" fill="${fill}"/>
      <path d="M10.6,-.9H.8" stroke="#fff" stroke-width=".9" opacity=".75"/>`;
    body = `<rect width="32" height="32" fill="#eef0f2"/>
      <path d="M0,19L8,23V27H32V32H0Z" fill="${ICON.ramp}" stroke="${ICON.edge}" stroke-width=".8"/>
      <rect x="8" y="27" width="24" height="5" fill="${ICON.street}"/>
      <path d="M8,22.6V27.4" stroke="#c0392b" stroke-width="2.4" stroke-linecap="round"/>
      <path d="M23.4,19L16.5,-1" stroke="#7d93b3" stroke-width="5"/>
      <g transform="translate(19.5,27) rotate(-28) scale(.9)">${shoe("#6d6d6d")}</g>
      <path d="M16.4,21.8L12,-1" stroke="#3d5a80" stroke-width="5"/>
      <g transform="translate(8.2,27) scale(.9)">${shoe(ICON.ink)}</g>
      <path d="M5,17.5l-2.4,-1.2M5.8,15.1l-1.2,-2.3M8.2,14.3l-.1,-2.6" stroke="${ICON.ink}" stroke-width="1.1" stroke-linecap="round"/>`;
  }
  return `<svg class="report-icon" width="32" height="32" viewBox="0 0 32 32" aria-hidden="true">${body}</svg>`;
}
const issuesText = v => issueList(v).map(k => RAMP_ISSUES[k][1]).join(", ");
// The ramp issues that apply to a corner: your own check first, then the published one.
const checkIssues = k => issueList(k.issues).join("+");
const rampIssues = c => (checks[c.corner_id] ? checkIssues(checks[c.corner_id]) : c.field_issues) || "";
function upgradeText(c) {
  const list = issueList(rampIssues(c));
  if (!list.length || c.overall === "missing") return "";
  const plural = c.overall === "present" && needsOf(c).length > 1;
  const diagonal = list.includes("diagonal"), rest = list.filter(i => i !== "diagonal").map(i => RAMP_ISSUES[i][1]);
  // Shared diagonal ramps (Standard Plan 422F) are still built where corners are tight, so
  // this says what the ramp does, not that it was built wrong.
  let text = diagonal ? "The corner has one ramp on its curve, aimed at the middle of the intersection rather than " +
    "lined up with either crosswalk, so people coming down it head toward the middle of the street. " +
    "A ramp lined up with each crosswalk would fix that." : "";
  if (rest.length) text += `${diagonal ? " The ramp also has: " : `The existing ramp${plural ? "s here: " : " here: "}`}${rest.join(", ")}.`;
  if (list.includes("no_warning")) text += " Without the yellow pad (detectable warning panel), people who are blind or have low vision can't tell where the sidewalk ends.";
  return text.trim();
}

// ------------------------------------------------------------------ evidence wording
function evidence(c) {
  const out = [];
  const k = checks[c.corner_id];
  const iss = s => (issuesText(s) ? ` Ramp condition: ${issuesText(s)}.` : "");
  if (k) out.push(`Checked in person on ${k.date}: ${checkText(c, k.ramps_for)}.${iss(checkIssues(k))}${k.notes ? ` ${k.notes}` : ""}`);
  else if (c.field_date) out.push(`A neighbor checked in person on ${c.field_date}: ${checkText(c, c.field_covers || "none")}.${iss(c.field_issues)}${c.field_notes ? ` ${c.field_notes}` : ""}`);
  if (c.city === "no record") out.push("SDOT's curb ramp inventory has no ramp recorded at this corner.");
  else if (c.city === "unassessed") out.push("SDOT's inventory only has unassessed placeholder records here (no built ramp).");
  else if (c.city === "partial") out.push("SDOT's inventory shows a ramp for one crossing only.");
  else if (c.city === "present") out.push(`SDOT's inventory shows ramps here (${ageText(c.city_install_date)}).`);
  if (c.ps_noramp_labels > 0 || c.ps_ramp_labels > 0) {
    const n = Number(c.ps_noramp_labels || 0), r = Number(c.ps_ramp_labels || 0);
    const img = c.ps_image_date ? ` (street imagery from ${c.ps_image_date})` : "";
    if (n && !r) out.push(`Project Sidewalk volunteers labeled "no curb ramp" here ${n} time${n > 1 ? "s" : ""}${img}.`);
    else if (r && !n) out.push(`Project Sidewalk volunteers labeled a curb ramp here${img}.`);
    else out.push(`Project Sidewalk volunteers labeled both a ramp and a missing ramp here${img}.`);
  }
  if (c.osm === "missing") out.push("OpenStreetMap shows raised curbs (no ramp) at this corner's crossings.");
  else if (c.osm === "partial") out.push("OpenStreetMap shows a lowered curb on one crossing and a raised curb on the other.");
  else if (c.osm === "present") out.push("OpenStreetMap shows lowered curbs here.");
  return out;
}

function shareUrl(params) {
  const u = new URL(location.pathname, location.origin);
  for (const [k, v] of Object.entries(params)) u.searchParams.set(k, v);
  return u.toString().replace(/%2C/g, ",");
}

function requestText(c) {
  const lines = [
    `Location: ${cornerTitle(c)}, Seattle, WA (${c.lat}, ${c.lon})`,
    `Request: ${c.overall === "present"
      ? (upgradeText(c) ? `Please upgrade this corner's curb ramps to current standards. ${upgradeText(c)}` : "Please check this corner's curb ramps.")
      : `Please install curb ramps at this corner. ${needText(c)}${upgradeText(c) ? ` ${upgradeText(c)} Please upgrade it too.` : ""}`}`,
    "",
    "What we know:",
    ...evidence(c).map(e => `- ${e}`),
    "",
    "Standard: City of Seattle Standard Plans 422a (curb ramps) and 422k (detectable warnings), 2026 edition.",
    `Map of this corner: ${shareUrl({ corner: shortId(c.corner_id) })}`,
  ];
  return lines.join("\n");
}

// ------------------------------------------------------------------ markers
function svgFor(k, fill, s, opts = {}) {
  const r = s / 2;
  const parts = [];
  if (opts.work) {
    const color = opts.work === "ongoing" ? "var(--ongoing)" : "var(--planned)";
    parts.push(`<circle cx="${r}" cy="${r}" r="${r + 3}" fill="none" stroke="${color}" stroke-width="3.5"` +
      (opts.work === "planned" ? ` stroke-dasharray="4 2.5"` : "") + `/>`);
  }
  const cross = (inset, w, halo) => {
    const a = s * inset, b = s * (1 - inset), d = `M${a},${a}L${b},${b}M${b},${a}L${a},${b}`;
    return (halo ? `<path d="${d}" stroke="#fff" stroke-width="${w + 3}" stroke-linecap="round"/>` : "") +
      `<path d="${d}" stroke="#000" stroke-width="${w}" stroke-linecap="round"/>`;
  };
  if (k === "x") parts.push(cross(0.18, Math.max(3, s * 0.17), true));
  else if (k === "q") {
    parts.push(`<circle cx="${r}" cy="${r}" r="${r - 1.5}" fill="#fff" stroke="#555" stroke-width="1.5"/>`,
      `<text x="${r}" y="${r}" dy=".36em" text-anchor="middle" font-size="${s * 0.62}" font-weight="700" font-family="system-ui,sans-serif" fill="#333">?</text>`);
  } else {
    parts.push(`<circle cx="${r}" cy="${r}" r="${r - 1.5}" fill="${fill}" stroke="#fff" stroke-width="2"/>`);
    if (k === "partial") parts.push(cross(0.33, Math.max(2, s * 0.12), false));
  }
  if (opts.checked) {
    const cr = Math.max(4, s * 0.22), cx = s - 1, cy = s - 1;
    parts.push(`<circle cx="${cx}" cy="${cy}" r="${cr}" fill="var(--checked)" stroke="#fff" stroke-width="1.5"/>`,
      `<path d="M${cx - cr * 0.5},${cy}l${cr * 0.35},${cr * 0.4}l${cr * 0.6},${-cr * 0.75}" fill="none" stroke="#fff" stroke-width="${Math.max(1.5, cr * 0.32)}" stroke-linecap="round" stroke-linejoin="round"/>`);
  }
  if (opts.filed) parts.push(`<circle cx="${s - 1}" cy="1" r="${Math.max(3.5, s * 0.2)}" fill="var(--filed)" stroke="#fff" stroke-width="1.5"/>`);
  if (opts.selected) parts.push(`<rect x="-4" y="-4" width="${s + 8}" height="${s + 8}" rx="4" fill="none" stroke="var(--selected)" stroke-width="2.5"/>`);
  return `<svg width="${s}" height="${s}" viewBox="0 0 ${s} ${s}" aria-hidden="true">${parts.join("")}</svg>`;
}

const sizeFor = z => (z >= 21 ? 34 : z >= 20 ? 30 : z >= 19 ? 26 : z >= 18 ? 20 : z >= 17 ? 15 : 11);

// ------------------------------------------------------------------ state + URL
const params = new URLSearchParams(location.search);
const state = {
  corner: byId.has(longId(params.get("corner") || "")) ? longId(params.get("corner")) : null,
  selected: new Set((params.get("sel") || "").split(",").map(longId).filter(id => byId.has(id))),
  tab: params.get("tab") || (params.get("corner") ? "corner" : params.get("sel") ? "group" : "key"),
};

// GPS state (see "GPS: center on me" below); declared early because writeUrl reads it.
const gps = { watch: null, following: false, moving: false, layer: null, button: null };

function writeUrl() {
  const p = new URLSearchParams();
  // While following GPS, the map center is the visitor's location: keep it
  // out of the address bar so a copied link doesn't reveal where they are.
  if (!gps.following) {
    const c = map.getCenter();
    p.set("lat", c.lat.toFixed(5));
    p.set("lng", c.lng.toFixed(5));
    p.set("z", map.getZoom());
  }
  if (state.corner) p.set("corner", shortId(state.corner));
  if (state.selected.size) p.set("sel", selParam(state.selected));
  if (state.tab && state.tab !== "key") p.set("tab", state.tab);
  history.replaceState(null, "", `${location.pathname}?${p.toString().replace(/%2C/g, ",")}`);
}

// ------------------------------------------------------------------ map
const map = L.map("map", { maxZoom: 21, zoomControl: true });
L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png", {
  maxZoom: 21, maxNativeZoom: 19,
  attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
}).addTo(map);
map.attributionControl.addAttribution("SDOT, Project Sidewalk");
L.control.scale({ imperial: true, metric: false }).addTo(map);

const esc = s => String(s ?? "").replace(/[&<>"']/g, ch => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]));

// Background: every SDOT ramp, colored by install date (newest drawn on top).
const rampLayer = L.layerGroup(DATA.city_ramps.slice()
  .sort((a, b) => (a.installed || "").localeCompare(b.installed || ""))
  .map(r => L.circleMarker([r.lat, r.lon], {
    radius: 4, weight: 1, color: "#0006", fillColor: ageColor(r.installed), fillOpacity: r.installed ? 0.9 : 0.5,
  }).bindPopup(`<strong>${esc(r.id)}</strong><br>${esc(r.desc)}<br><span class="dot" style="background:${ageColor(r.installed)}"></span>${ageText(r.installed)}` +
    (r.condition ? `<br>condition ${esc(r.condition)}` : "")))).addTo(map);

// Background: SDOT work orders (planned purple, ongoing pink).
// Work orders at a mapped corner already show as that corner's ring.
const atCorner = new Set(corners.flatMap(c => (c.work_orders || []).map(w => `${w.id}|${w.started}`)));
const workLayer = L.layerGroup(DATA.work_orders.map(w => {
  const st = workState(w);
  if (!st || atCorner.has(`${w.id}|${w.started}`)) return null;
  return L.circleMarker([w.lat, w.lon], {
    radius: 6, weight: 2.5, color: st === "ongoing" ? "#e0389a" : "#7a3fc2", fill: false,
    dashArray: st === "planned" ? "3 2" : null,
  }).bindPopup(`<strong>${esc(w.id)}</strong> ${esc(w.intersection)}<br>${esc(workText(w))}<br>` +
    `<span class="status ${st}">${st}</span>`);
}).filter(Boolean)).addTo(map);

const markers = new Map();
function iconFor(c) {
  const s = sizeFor(map.getZoom()) - (c.corner_type === "corner" ? 0 : 3);
  return L.divIcon({
    className: "m" + (c.corner_id === state.corner ? " current" : ""),
    html: svgFor(kind(c), ageColor(c.city_install_date), s, {
      work: cornerWork(c), filed: !!c.request_filed, selected: state.selected.has(c.corner_id),
      checked: !!(checks[c.corner_id] || c.field_date),
    }),
    // At least 24 px to tap (WCAG 2.5.8), however small the drawing.
    iconSize: [Math.max(s, 24), Math.max(s, 24)], iconAnchor: [Math.max(s, 24) / 2, Math.max(s, 24) / 2],
  });
}
for (const c of corners) {
  const m = L.marker([c.lat, c.lon], {
    icon: L.divIcon({ html: "" }), keyboard: true, zIndexOffset: 1000,
    title: `${cornerTitle(c)}: ${statusLabel(c)[1]}`, alt: cornerTitle(c),
  }).addTo(map);
  m.on("click", () => selectCorner(c.corner_id, { pan: false }));
  markers.set(c.corner_id, m);
}
// Keyboard: markers are focusable (Tab); Enter or Space opens the corner.
document.getElementById("map").addEventListener("keydown", e => {
  const id = e.target.closest?.(".leaflet-marker-icon")?.dataset.corner;
  if (id && (e.key === "Enter" || e.key === " ")) {
    e.preventDefault();
    selectCorner(id, { pan: false });
  }
});
function refreshMarker(id) {
  const m = markers.get(id).setIcon(iconFor(byId.get(id)));
  if (m.getElement()) m.getElement().dataset.corner = id; // for keyboard activation
}
const refreshMarkers = () => corners.forEach(c => refreshMarker(c.corner_id));
map.on("zoomend", refreshMarkers);
map.on("moveend", writeUrl);

// Initial view: URL > selected corner > whole corridor.
const lat = parseFloat(params.get("lat")), lng = parseFloat(params.get("lng")), z = parseInt(params.get("z"), 10);
if (Number.isFinite(lat) && Number.isFinite(lng)) map.setView([lat, lng], Number.isFinite(z) ? z : 18);
else if (state.corner) map.setView([byId.get(state.corner).lat, byId.get(state.corner).lon], Number.isFinite(z) ? z : CORNER_ZOOM);
else map.fitBounds(L.latLngBounds(corners.map(c => [c.lat, c.lon])), { padding: [20, 20] });
refreshMarkers();

document.getElementById("layer-ramps").addEventListener("change", e => (e.target.checked ? rampLayer.addTo(map) : rampLayer.remove()));
document.getElementById("layer-work").addEventListener("change", e => (e.target.checked ? workLayer.addTo(map) : workLayer.remove()));

// ------------------------------------------------------------------ tabs
function showTab(name, { focus = false } = {}) {
  state.tab = name;
  document.querySelectorAll(".tabs [role=tab]").forEach(b => {
    const on = b.dataset.tab === name;
    b.setAttribute("aria-selected", on);
    b.tabIndex = on ? 0 : -1;
    document.getElementById(b.getAttribute("aria-controls")).hidden = !on;
    if (on && focus) b.focus();
  });
  writeUrl();
}
document.querySelectorAll(".tabs [role=tab]").forEach(b => b.addEventListener("click", () => showTab(b.dataset.tab)));
document.querySelector(".tabs").addEventListener("keydown", e => {
  const tabs = [...document.querySelectorAll(".tabs [role=tab]")];
  const i = tabs.findIndex(t => t.dataset.tab === state.tab);
  if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
    const next = tabs[(i + (e.key === "ArrowRight" ? 1 : tabs.length - 1)) % tabs.length];
    showTab(next.dataset.tab, { focus: true });
  }
});
document.addEventListener("click", e => {
  const go = e.target.closest("[data-goto]");
  if (go) { e.preventDefault(); showTab(go.dataset.goto); }
});

// ------------------------------------------------------------------ clipboard + toast
function toast(msg) {
  const t = document.getElementById("toast");
  t.textContent = msg;
  t.classList.add("show");
  clearTimeout(toast.timer);
  toast.timer = setTimeout(() => t.classList.remove("show"), 2200);
}
async function copy(text, what = "Copied") {
  try {
    await navigator.clipboard.writeText(text);
  } catch {
    const ta = Object.assign(document.createElement("textarea"), { value: text });
    document.body.append(ta);
    ta.select();
    document.execCommand("copy");
    ta.remove();
  }
  toast(what);
}

// Phones often open GitHub links in the GitHub app, which can drop a prefilled body.
// Copy it first (while this page still has focus) so it's one paste away.
function copyIssueBody(url) {
  const body = new URL(url).searchParams.get("body");
  if (!body) return;
  navigator.clipboard?.writeText(body).catch(() => {});
  toast("Issue text copied. If GitHub opens an empty issue, paste it in.");
}
document.addEventListener("click", e => {
  const a = e.target.closest(`a[href^="https://github.com/${REPO}/issues/new"]`);
  if (a) copyIssueBody(a.href);
});

function issueUrl(cs) {
  const ids = cs.map(c => c.corner_id);
  const title = `Request filed: ${ids.length === 1 ? cornerTitle(cs[0]) : `${ids.length} corners`}`;
  const body = [
    "<!-- Please don't include your name, phone, or email. -->",
    "",
    `Corners: ${ids.join(", ")}`,
    "Filed with: (SDOT Curb Ramp Request form / Find It, Fix It / Customer Service Bureau / other)",
    "Date filed: ",
    "Confirmation or tracking number: ",
    "",
    `Map: ${shareUrl(ids.length === 1 ? { corner: shortId(ids[0]) } : { sel: selParam(ids), tab: "group" })}`,
  ].join("\n");
  return `https://github.com/${REPO}/issues/new?title=${encodeURIComponent(title)}&body=${encodeURIComponent(body)}&labels=request-filed`;
}

// ------------------------------------------------------------------ corner detail
function selectCorner(id, { pan = true } = {}) {
  const prev = state.corner;
  state.corner = id;
  if (prev && byId.has(prev)) refreshMarker(prev);
  refreshMarker(id);
  const c = byId.get(id);
  if (pan) map.setView([c.lat, c.lon], Math.max(map.getZoom(), CORNER_ZOOM));
  renderCorner();
  showTab("corner");
  if (window.matchMedia("(max-width: 760px)").matches && !pan) {
    document.getElementById("pane-corner").scrollIntoView({
      behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth", block: "start" });
  }
}

// One line per distinct piece of work (a project often covers several ramps).
function workRows(wos) {
  if (!wos.length) return "";
  const lines = new Map();
  for (const w of wos) {
    const key = `${workState(w)}|${workText(w)}`;
    lines.set(key, (lines.get(key) || 0) + 1);
  }
  const html = [...lines].map(([key, n]) => {
    const [st, text] = key.split("|");
    return `<span class="status ${st}">${st}</span> ${esc(text)}${n > 1 ? ` (${n} ramps)` : ""}`;
  });
  return `<tr><th>SDOT work</th><td>${html.join("<br>")}</td></tr>`;
}

function renderCorner() {
  const el = document.getElementById("corner-detail");
  const c = byId.get(state.corner);
  if (!c) return;
  const [cls, label] = statusLabel(c);
  const work = cornerWork(c);
  const selected = state.selected.has(c.corner_id);
  const srcRow = (name, value, extra) => `<tr><th>${name}</th><td>${esc(value)}${extra ? `<br><span class="small">${extra}</span>` : ""}</td></tr>`;
  const wos = (c.work_orders || []).filter(w => workState(w));
  const mine = checks[c.corner_id];

  el.innerHTML = `
    <h2 class="corner-title">${esc(cornerTitle(c))}</h2>
    ${c.corner_type !== "corner" ? `<p class="small">This side of the T-intersection has no side street, so it only needs a ramp for crossing ${MAIN_STREET}.</p>` : ""}
    <p><span class="status ${cls}">${esc(label)}</span>
       ${work ? `<span class="status ${work}">${work === "ongoing" ? "City work this week" : "City work planned"}</span>` : ""}
       ${c.request_filed ? `<span class="status" style="background:var(--filed)">Request filed</span>` : ""}
       ${mine ? `<span class="status" style="background:var(--checked)">You checked this ${esc(mine.date)}</span>`
         : c.field_date ? `<span class="status" style="background:var(--checked)">Checked in person ${esc(c.field_date)}</span>` : ""}</p>
    ${mine ? `<p class="small">Shown as you saw it, in this browser only. <button class="link" data-goto="checks">Send your checks</button> so the map is fixed for everyone.</p>` : ""}
    ${needText(c) ? `<p>${esc(needText(c))}</p>` : ""}
    ${upgradeText(c) ? `<p><span class="status upgrade">Needs upgrade</span> ${esc(upgradeText(c))}</p>` : ""}
    ${c.sources_disagree ? `<p class="small">The sources disagree here${c.note ? `: ${esc(c.note)}` : ""}. Worth a look in person before filing.</p>` : ""}

    <p class="small where" id="check-where">${whereText(c)}</p>
    <details class="report" data-report ${reportOpen(c) ? "open" : ""}>
      <summary>${mine ? "Your report on this corner" : "Report what's here"}</summary>
      ${reportBody(c)}
    </details>

    <div class="buttons">
      <button class="button primary" data-action="copy-request">Copy request text</button>
      <button class="button ${selected ? "on" : ""}" data-action="toggle-select" aria-pressed="${selected}">${selected ? "In group request ✓" : "Add to group request"}</button>
      <button class="button" data-action="copy-link">Copy link to this corner</button>
    </div>
    <div class="buttons">
      <a class="button" href="${SDOT_FORM}" target="_blank" rel="noopener">SDOT ramp form (ADA)</a>
      <a class="button" href="${CSB_PORTAL}" target="_blank" rel="noopener">General request</a>
      <a class="button" href="${issueUrl([c])}" target="_blank" rel="noopener">I filed this</a>
    </div>
    ${needsWork(c) ? `<p class="small">On site? <a href="../../ar/?area=${encodeURIComponent(AREA.slug)}&corner=${encodeURIComponent(shortId(c.corner_id))}">See a standard ramp at this corner in AR</a>, to check what's in the way.</p>` : ""}
    <p class="small">Not sure which form? See <button class="link" data-goto="request">How to request</button>.</p>

    <h2>What each source says</h2>
    <table class="facts">
      ${srcRow("SDOT inventory", c.city,
        (c.city_ramp_count ? `<span class="dot" style="background:${ageColor(c.city_install_date)}"></span>${esc(ageText(c.city_install_date))}` : "") +
        (c.city_condition ? `, condition ${esc(c.city_condition.toLowerCase())}` : "") +
        (c.city_covers ? `<br>covers ${esc(c.city_covers.split("+").map(k => crossingName(c, k)).join(" and "))}` : ""))}
      ${srcRow("Project Sidewalk", c.ps,
        (c.ps_ramp_labels || c.ps_noramp_labels ? `${c.ps_ramp_labels || 0} ramp / ${c.ps_noramp_labels || 0} no-ramp labels` : "") +
        (c.ps_image_date ? `, imagery ${esc(c.ps_image_date)}` : "") +
        (c.ps_ramp_issues ? `<br>ramp issues: ${esc(c.ps_ramp_issues)}` : ""))}
      ${srcRow("OpenStreetMap", c.osm, c.osm_kerbs ? esc(c.osm_kerbs.replace(/main:/g, `${AREA.short}: `).replace(/cross:/g, "side street: ").replace(/\?:/g, "")) : "")}
      ${workRows(wos)}
      ${c.field_date ? srcRow("In person", c.field, `checked ${esc(c.field_date)}${c.field_notes ? `: ${esc(c.field_notes)}` : ""}`) : ""}
      ${c.request_filed ? `<tr><th>Request</th><td>Filed ${esc(c.request_date)} ${esc(c.request_ref)} ${esc(c.request_status)}</td></tr>` : ""}
    </table>

    <h2>Request text</h2>
    <pre class="request" tabindex="0" role="region" aria-label="Request text">${esc(requestText(c))}</pre>
    <p class="small">Corner ID <code>${esc(c.corner_id)}</code> ·
      <a href="https://www.google.com/maps/@?api=1&amp;map_action=pano&amp;viewpoint=${c.lat},${c.lon}" target="_blank" rel="noopener">Street View</a> ·
      <a href="https://www.openstreetmap.org/?mlat=${c.lat}&amp;mlon=${c.lon}#map=20/${c.lat}/${c.lon}" target="_blank" rel="noopener">OpenStreetMap</a></p>`;
}

document.getElementById("corner-detail").addEventListener("click", e => {
  const b = e.target.closest("[data-action]");
  if (!b) return;
  const c = byId.get(state.corner);
  if (b.dataset.action === "copy-request") copy(requestText(c), "Request text copied");
  if (b.dataset.action === "copy-link") copy(shareUrl({ corner: shortId(c.corner_id) }), "Link copied");
  if (b.dataset.action === "toggle-select") { toggleSelected(c.corner_id); renderCorner(); }
});
// ------------------------------------------------------------------ report one corner
// One corner at a time: the corner open in the panel. Each tick saves right away.
state.reportOpen = null; // null: open when you've reported this corner or your phone is at it
function reportOpen(c) {
  if (state.reportOpen != null) return state.reportOpen;
  const fix = freshFix();
  return !!checks[c.corner_id] || !!(fix && map.distance([fix.lat, fix.lng], [c.lat, c.lon]) * FT < ON_SITE_FT);
}
const crossShort = (c, n) => (n === "main" ? MAIN_STREET : baseStreet(c));

function reportBody(c) {
  const k = checks[c.corner_id];
  const covered = k ? coveredBy(k.ramps_for) : needsOf(c), issues = issueList(k?.issues);
  const noRamps = !!k && !covered.length;
  const box = (name, label, on, disabled, icon) => `<label class="check"><input type="checkbox" name="${name}"
    ${on ? "checked" : ""} ${disabled ? "disabled" : ""}>${icon}<span>${esc(label)}</span></label>`;
  const siblings = intersectionCorners(c).filter(x => x !== c);
  const last = siblings.map(x => [x, checks[x.corner_id]]).filter(([, v]) => v).sort((a, b) => (a[1].at || 0) - (b[1].at || 0)).pop();
  const todo = siblings.filter(x => !checks[x.corner_id]);
  return `
    <div class="check-diagram">${checkDiagram(c)}</div>
    <p><strong>${esc(CORNER_WORDS[c.corner][0].toUpperCase() + CORNER_WORDS[c.corner].slice(1))} corner.</strong>
      Tick anything missing or wrong. Each tick is saved.</p>
    <div class="report-list">
      ${needsOf(c).map(n => box(`miss|${n}`, `No ramp to cross ${crossShort(c, n)}`, !!k && !covered.includes(n), false, reportIcon("miss", c, n))).join("")}
      ${Object.entries(RAMP_ISSUES).map(([i, [label]]) => box(i, label, issues.includes(i), noRamps, reportIcon(i, c))).join("")}
    </div>
    <div class="buttons">
      <button class="button ${k && k.ramps_for === needsOf(c).join("+") && !issues.length ? "on" : ""}" type="button" data-report-action="ok">${reportIcon("ok", c)}Nothing wrong here</button>
      ${last && !k ? `<button class="button" type="button" data-report-action="same" data-from="${esc(last[0].corner_id)}">Same as ${esc(last[0].corner)}</button>` : ""}
      ${k ? `<button class="button" type="button" data-report-action="clear">Clear</button>` : ""}
    </div>
    <label class="field">Note (optional)
      <input type="text" name="notes" maxlength="200" value="${esc(k?.notes || "")}"
        placeholder="e.g. ramp points into the middle of the intersection"></label>
    ${freshFix() ? "" : `<p class="small">Tip: turn on your location (the button under the zoom buttons) first, and each
      report records how far you were from the corner, which shows it was made on site. Only that distance is
      saved, never your position.</p>`}
    <p class="small">${k ? `Saved in this browser: ${esc(cornerDescription(c, k))}.` : "Nothing saved for this corner yet."}
      ${todo.length ? ` Next: ${todo.map(x => `<button class="link" type="button" data-report-corner="${esc(x.corner_id)}">${esc(x.corner)}</button>`).join(", ")}.`
        : ` Every corner here is done. <button class="link" type="button" data-goto="checks">Send your checks</button>.`}</p>`;
}

function saveReport(c, { missing = [], issues = [], notes = checks[c.corner_id]?.notes || "" }) {
  const covered = needsOf(c).filter(n => !missing.includes(n));
  const ramps_for = covered.length ? covered.join("+") : "none";
  const old = checks[c.corner_id];
  checks[c.corner_id] = {
    date: new Date().toLocaleDateString("en-CA"), // YYYY-MM-DD, local
    ramps_for, issues: ramps_for === "none" ? "" : issues.join("+"), notes,
    ...(onSite(c) || (old?.distance_ft != null ? { distance_ft: old.distance_ft, accuracy_ft: old.accuracy_ft } : {})),
    at: Date.now(), // order of saving, for "Same as"
  };
  afterReport(c);
}
function afterReport(c, focus) {
  saveChecks();
  applyCheck(c);
  refreshMarker(c.corner_id);
  renderCorner();
  renderChecks();
  renderList();
  if (focus) document.querySelector(`#corner-detail [data-report] [name="${focus}"]`)?.focus();
}
function readReport(box) {
  const els = [...box.querySelectorAll("input[type=checkbox]")];
  return {
    missing: els.filter(i => i.checked && i.name.startsWith("miss|")).map(i => i.name.slice(5)),
    issues: els.filter(i => i.checked && RAMP_ISSUES[i.name]).map(i => i.name),
    notes: box.querySelector("[name=notes]").value.trim().replace(/\s+/g, " "),
  };
}
const detail = document.getElementById("corner-detail");
detail.addEventListener("change", e => {
  const box = e.target.closest("[data-report]");
  if (!box) return;
  saveReport(byId.get(state.corner), readReport(box));
  if (e.target.type === "checkbox") {
    document.querySelector(`#corner-detail [data-report] [name="${e.target.name}"]`)?.focus();
    toast(`Saved (${myChecks().length} to send)`);
  }
});
detail.addEventListener("toggle", e => {
  if (e.target.matches("[data-report]")) state.reportOpen = e.target.open;
}, true);
detail.addEventListener("click", e => {
  const go = e.target.closest("[data-report-corner]");
  if (go) { state.reportOpen = true; return selectCorner(go.dataset.reportCorner, { pan: false }); }
  const b = e.target.closest("[data-report-action]");
  if (!b) return;
  const c = byId.get(state.corner);
  if (b.dataset.reportAction === "ok") { saveReport(c, {}); toast("Saved: nothing wrong here"); }
  if (b.dataset.reportAction === "clear") { delete checks[c.corner_id]; afterReport(c); toast("Cleared"); }
  if (b.dataset.reportAction === "same") {
    const k = checks[b.dataset.from], from = byId.get(b.dataset.from);
    const missing = needsOf(from).filter(n => !coveredBy(k.ramps_for).includes(n)).filter(n => needsOf(c).includes(n));
    saveReport(c, { missing, issues: issueList(k.issues), notes: k.notes || "" });
    toast(`Saved, same as ${from.corner}`);
  }
});

// With location on, a check records how far the phone was from the corner, and how
// precise the fix was. Never the position itself.
const FT = 3.28084;
function freshFix() {
  return gps.last && Date.now() - gps.last.at < 120e3 ? gps.last : null;
}
function onSite(c) {
  const fix = freshFix();
  if (!fix) return null;
  return { distance_ft: Math.round(map.distance([fix.lat, fix.lng], [c.lat, c.lon]) * FT / 5) * 5,
           accuracy_ft: Math.round(fix.accuracy * FT / 5) * 5 };
}
// Where the phone says you are, compared with the intersection on screen.
function whereText(c) {
  const fix = freshFix();
  if (!fix) return "";
  const [near, d] = nearestCorner(fix.lat, fix.lng);
  if (near.intersection_id !== c.intersection_id && d < 450) {
    return `<strong>Your phone puts you at ${esc(MAIN_STREET)} &amp; ${esc(baseStreet(near))}</strong>, not this intersection.
      <button class="link" type="button" data-gps-corner="${esc(near.corner_id)}">Check that one instead</button>?`;
  }
  const here = Math.min(...intersectionCorners(c).map(x => map.distance([fix.lat, fix.lng], [x.lat, x.lon])));
  return here * FT < 300
    ? `📍 You're here (about ${Math.round(here * FT / 10) * 10} ft from the nearest corner). Your reports will say so.`
    : `Your phone puts you about ${Math.round(here * FT / 10) * 10} ft away, so reports here won't count as on site.`;
}
function locatedText(k) {
  return k.distance_ft != null ? `on site, ${k.distance_ft} ft from the corner (±${k.accuracy_ft} ft)` : "";
}

function intersectionCorners(c) {
  const order = ["NW", "NE", "SW", "SE"];
  return corners.filter(x => x.intersection_id === c.intersection_id)
    .sort((a, b) => order.indexOf(a.corner) - order.indexOf(b.corner));
}
// A plan of the intersection: the main street runs up and down. Each corner has a slot
// for each ramp it needs, at the curb by its crosswalk: yellow for a ramp with a pad,
// gray without one, an X for no ramp, dashed until the corner is reported. The open
// corner is outlined; tapping another corner opens it.
function checkDiagram(c) {
  const S = 220, A = 82, B = 138; // street edges
  const parts = [
    `<rect width="${S}" height="${S}" fill="var(--soft)"/>`,
    `<rect x="${A}" width="${B - A}" height="${S}" fill="var(--street)"/>`,
    `<rect y="${A}" width="${S}" height="${B - A}" fill="var(--street)"/>`,
    `<text x="${(A + B) / 2}" y="16" text-anchor="middle" class="street-name">${esc(AREA.short)}</text>`,
    `<text x="10" y="${(A + B) / 2 + 4}" class="street-name">${esc(baseStreet(c).replace(/^[NSEW]+ /, ""))}</text>`,
  ];
  for (const x of intersectionCorners(c)) {
    const west = x.corner.endsWith("W"), north = x.corner.startsWith("N");
    const cx = west ? A : B, cy = north ? A : B, sx = west ? -1 : 1, sy = north ? -1 : 1;
    const k = checks[x.corner_id], covered = k ? coveredBy(k.ramps_for) : [], noPad = issueList(k?.issues).includes("no_warning");
    const current = x.corner_id === c.corner_id;
    parts.push(`<g data-report-corner="${esc(x.corner_id)}" class="corner">
      <rect x="${west ? 2 : B + 2}" y="${north ? 2 : B + 2}" width="${A - 4}" height="${A - 4}" rx="6"
        fill="${k ? "var(--checked-soft)" : "transparent"}" ${current ? 'stroke="var(--checked)" stroke-width="3"' : ""}/>
      <text x="${west ? A / 2 : B + A / 2}" y="${north ? A / 2 : B + A / 2}" dy=".35em" text-anchor="middle" class="corner-name">${x.corner}</text></g>`);
    const diagonal = issueList(k?.issues).includes("diagonal");
    if (diagonal && covered.length) {
      // one ramp at the apex, aimed at the middle of the intersection
      const ax = cx + sx * 12, ay = cy + sy * 12, turn = sx === sy ? -45 : 45;
      parts.push(`<rect x="${ax - 8}" y="${ay - 4}" width="16" height="8" transform="rotate(${turn} ${ax} ${ay})"
        fill="${noPad ? "#9a9a9a" : "#f2c200"}" stroke="var(--fg)" stroke-width="1"/>`);
    }
    for (const n of needsOf(x)) {
      if (diagonal && k && covered.includes(n)) continue; // the apex ramp stands in for it
      // ramp for crossing the side street sits on its curb; for crossing the main street, on the main street's curb
      const [w, h] = n === "cross" ? [22, 9] : [9, 22];
      // with a central ramp at the apex, slide the other marks along the curb to clear it
      const slide = diagonal ? 12 : 0;
      const rx = n === "cross" ? cx + sx * (8 + slide) + (sx < 0 ? -w : 0) : cx + (sx < 0 ? -w : 0);
      const ry = n === "cross" ? cy + (sy < 0 ? -h : 0) : cy + sy * (8 + slide) + (sy < 0 ? -h : 0);
      if (!k) {
        parts.push(`<rect x="${rx}" y="${ry}" width="${w}" height="${h}" fill="none" stroke="var(--muted)" stroke-dasharray="3 2"/>`);
      } else if (!covered.includes(n)) {
        const mx = rx + w / 2, my = ry + h / 2;
        parts.push(`<path d="M${mx - 6},${my - 6}L${mx + 6},${my + 6}M${mx + 6},${my - 6}L${mx - 6},${my + 6}" stroke="var(--fg)" stroke-width="3" stroke-linecap="round"/>`);
      } else {
        parts.push(`<rect x="${rx}" y="${ry}" width="${w}" height="${h}" fill="${noPad ? "#9a9a9a" : "#f2c200"}" stroke="var(--fg)" stroke-width="1"/>`);
      }
    }
  }
  return `<svg viewBox="0 0 ${S} ${S}" width="${S}" height="${S}" role="img"
      aria-label="Plan of ${esc(MAIN_STREET)} and ${esc(baseStreet(c))}, ${esc(c.corner)} corner selected">${parts.join("")}</svg>
    <p class="small">Yellow: ramp with a yellow pad. Gray: ramp without one. ✕: no ramp. Tap a corner to report it.</p>`;
}

// ------------------------------------------------------------------ checks: review + send
const csvCell = v => (/[",\n]/.test(v) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
function checksCsv(cs) {
  return ["corner_id,date_checked,ramps_for,yellow_pad,ramp_issues,notes,distance_ft,accuracy_ft",
    ...cs.map(c => {
      const k = checks[c.corner_id];
      const iss = issueList(k.issues), other = iss.filter(i => i !== "no_warning").join("+");
      const pad = k.ramps_for === "none" ? "" : iss.includes("no_warning") ? "no" : "yes";
      return [c.corner_id, k.date, k.ramps_for, pad, other, k.notes || "", k.distance_ft ?? "", k.accuracy_ft ?? ""].map(csvCell).join(",");
    }),
  ].join("\n");
}
// "no ramp east–west, no yellow pad, older crisscross style at all 4 corners; ramps both directions at NE"
function cornerDescription(c, k) {
  const covered = coveredBy(k.ramps_for), need = needsOf(c);
  if (!covered.length) return need.length > 1 ? "no ramps" : "no ramp";
  const miss = need.filter(n => !covered.includes(n));
  // A central ramp stands in for "ramps both ways": saying both would contradict itself.
  const central = issueList(k.issues).includes("diagonal");
  return [miss.length ? miss.map(n => `no ramp to cross ${crossShort(c, n)}`).join(", ") : central ? "" : need.length > 1 ? "ramps both ways" : "ramp",
    ...issueList(k.issues).map(i => RAMP_ISSUES[i][1])].filter(Boolean).join(", ");
}
function intersectionSummary(cs) {
  const byAnswer = new Map();
  for (const c of cs) {
    const label = cornerDescription(c, checks[c.corner_id]);
    byAnswer.set(label, [...(byAnswer.get(label) || []), c.corner]);
  }
  const total = intersectionCorners(cs[0]).length;
  return [...byAnswer].map(([label, where]) =>
    `${label} ${where.length === total && total > 1 ? `at all ${total} corners` : `at ${where.join(", ")}`}`).join("; ");
}
const checkGroups = cs => groupByIntersection(cs).map(g => [`${MAIN_STREET} & ${baseStreet(g[0])}`, g]);

const ON_SITE_FT = 300;
const onSiteGroup = g => g.some(c => checks[c.corner_id].distance_ft != null && checks[c.corner_id].distance_ft < ON_SITE_FT);

// Opens .github/ISSUE_TEMPLATE/field-check.yml with every field filled in: each
// field's id is a query parameter.
// The whole report as Markdown: the issue's body, and what Send copies to the clipboard.
function checksIssueBody(cs, csvInBody = true) {
  const groups = checkGroups(cs);
  const notes = [...new Set(cs.map(c => checks[c.corner_id].notes).filter(Boolean))];
  return [
    "<!-- Please don't include your name, phone, or email. -->",
    "",
    ...groups.map(([name, g]) => `- **${name}**: ${intersectionSummary(g)}${onSiteGroup(g) ? " (phone location on site)" : ""}`),
    ...(notes.length ? ["", ...notes.map(n => `> ${n}`)] : []),
    "",
    "### Photos (optional)",
    "",
    "Drag photos of the corners here, or attach them from your phone.",
    "",
    "### Rows for `data/field-checks.csv`",
    "",
    ...(csvInBody ? ["```csv", checksCsv(cs), "```"] : ["(Too long for a link: paste the rows from your clipboard here.)"]),
    "",
    `Map: ${shareUrl({ sel: selParam(cs.map(c => c.corner_id)), tab: "group" })}`,
  ].join("\n");
}
// A plain title + body link: the GitHub app (which phones open these links in) ignores
// issue-form fields, and some versions ignore the body too, so Send also copies the body.
// The label sticks only for people who can label issues; the rest are labeled by hand.
function checksIssueUrl(cs, csvInBody = true) {
  const groups = checkGroups(cs);
  const p = new URLSearchParams({
    title: `Checked in person: ${MAIN_STREET} & ${groups.map(([, g]) => baseStreet(g[0])).join(", ")}`,
    body: checksIssueBody(cs, csvInBody),
    labels: "field-check",
  });
  return `https://github.com/${REPO}/issues/new?${p.toString().replace(/\+/g, "%20")}`;
}

function renderChecks() {
  const cs = myChecks();
  const count = document.getElementById("checks-count");
  count.hidden = !cs.length;
  count.textContent = cs.length;
  const el = document.getElementById("checks-body");
  if (!cs.length) {
    el.innerHTML = `<p>No checks saved in this browser. Open a corner on the map and use <strong>Report what's here</strong></p>`;
    return;
  }
  const n = checkGroups(cs).length;
  el.innerHTML = `
    <ul class="checks">${checkGroups(cs).map(([name, g]) => {
      const dates = [...new Set(g.map(c => checks[c.corner_id].date))].join(", ");
      const sent = g.every(c => checks[c.corner_id].sent) ? ` · sent ${esc(checks[g[0].corner_id].sent)}` : "";
      const notes = [...new Set(g.map(c => checks[c.corner_id].notes).filter(Boolean))].join(" ");
      return `<li><button class="link" data-focus-check="${esc(g[0].corner_id)}">${esc(name)}</button><br>
        <span class="small">${esc(intersectionSummary(g))}${onSiteGroup(g) ? " · 📍 on site" : ""}${notes ? `. ${esc(notes)}` : ""}<br>${esc(dates)}${sent}</span></li>`;
    }).join("")}</ul>
    <div class="buttons">
      <button class="button primary" data-check-action="send">Send ${n === 1 ? "this intersection" : `these ${n} intersections`} on GitHub</button>
      <button class="button" data-check-action="copy">Copy as CSV</button>
      <button class="button" data-check-action="forget">Forget all</button>
    </div>
    <p class="small">Sending opens a new GitHub issue with your checks filled in (you need a free GitHub account),
      where you can also add photos. Once they're added to the data, everyone sees the corrected corners and the
      checks clear here on their own. No GitHub account? Use <strong>Copy as CSV</strong> and send the text to
      whoever runs this map.</p>`;
}
document.getElementById("checks-body").addEventListener("click", e => {
  const f = e.target.closest("[data-focus-check]");
  if (f) return selectCorner(f.dataset.focusCheck);
  const b = e.target.closest("[data-check-action]");
  if (!b) return;
  const cs = myChecks();
  if (b.dataset.checkAction === "copy") copy(checksCsv(cs), "Checks copied as CSV");
  if (b.dataset.checkAction === "send") {
    let url = checksIssueUrl(cs);
    if (url.length > 7500) url = checksIssueUrl(cs, false); // GitHub refuses very long links
    // Copy the full report (even when the link had to leave the rows out) before opening GitHub:
    // once the new tab has focus, this page can't write the clipboard.
    navigator.clipboard?.writeText(checksIssueBody(cs)).catch(() => {});
    window.open(url, "_blank", "noopener");
    toast("Report copied. If GitHub opens an empty issue, paste it in.");
    const day = new Date().toLocaleDateString("en-CA");
    cs.forEach(c => { checks[c.corner_id].sent = day; });
    saveChecks();
    renderChecks();
  }
  if (b.dataset.checkAction === "forget" && confirm(`Forget ${cs.length} check${cs.length > 1 ? "s" : ""} saved in this browser?`)) {
    cs.forEach(c => { delete checks[c.corner_id]; applyCheck(c); refreshMarker(c.corner_id); });
    saveChecks();
    renderChecks();
    renderList();
    if (state.corner) renderCorner();
  }
});

// ------------------------------------------------------------------ group requests
function toggleSelected(id, on = !state.selected.has(id)) {
  on ? state.selected.add(id) : state.selected.delete(id);
  refreshMarker(id);
  renderGroup();
  renderList();
  writeUrl();
}

function groupByIntersection(cs) {
  const groups = new Map();
  for (const c of cs) {
    if (!groups.has(c.intersection_id)) groups.set(c.intersection_id, []);
    groups.get(c.intersection_id).push(c);
  }
  return [...groups.values()];
}
const order = new Map(corners.map((c, i) => [c.corner_id, i]));
const selectedCorners = () => [...state.selected].map(id => byId.get(id)).sort((a, b) => order.get(a.corner_id) - order.get(b.corner_id));

function packetText(groups, n, total) {
  const cs = groups.flat();
  return [
    `Curb ramp request ${n} of ${total}: ${MAIN_STREET} & ${groups.map(g => baseStreet(g[0])).join(", and ")}, Seattle, WA`,
    "",
    ...cs.flatMap(c => [`${cornerTitle(c)} (${c.lat}, ${c.lon})`, `  ${c.overall === "partial" ? needText(c) : "No curb ramps."}`,
      ...evidence(c).map(e => `  - ${e}`), ""]),
    `Map of these corners: ${shareUrl({ sel: selParam(cs.map(c => c.corner_id)), tab: "group" })}`,
  ].join("\n");
}

function letterText(cs) {
  const missing = cs.filter(c => c.overall === "missing").length;
  const partial = cs.filter(c => c.overall === "partial").length;
  const streets = [...new Set(cs.map(baseStreet))];
  const onHold = cs.filter(c => needsWork(c) && (c.sdot_projects || "").includes("on-hold"));
  return [
    "To the Seattle Department of Transportation and our councilmember,",
    "",
    `We are neighbors along ${MAIN_STREET} in ${AREA.name}, between ${AREA.extent.replace(" to ", " and ")}. ` +
      `People pushing strollers and wheelchairs, using walkers, or pulling carts along this stretch run into curbs with no ramp at almost every block.`,
    "",
    `We have identified ${cs.length} corner${cs.length > 1 ? "s" : ""} that need${cs.length > 1 ? "" : "s"} curb ramps` +
      (missing && partial ? ` (${missing} with no ramp at all, ${partial} with a ramp for only one of the two crossings)` : "") +
      `, at ${MAIN_STREET} and ${streets.join(", ")}.` +
      " Each one is backed by at least one public dataset: SDOT's own curb ramp inventory, Project Sidewalk (University of Washington), and OpenStreetMap.",
    ...(onHold.length ? ["", `${onHold.length} of these corners are already part of ${onHoldText(onHold)}. We ask that it be restarted.`] : []),
    "",
    "We ask SDOT to schedule curb ramps at these corners, and to tell us the expected timeline.",
    "",
    `Corner-by-corner details and evidence: ${shareUrl({ sel: selParam(cs.map(c => c.corner_id)), tab: "group" })}`,
    "",
    "Signed,",
    "(names and addresses of neighbors)",
  ].join("\n");
}

function renderGroup() {
  const count = document.getElementById("sel-count");
  count.hidden = !state.selected.size;
  count.textContent = state.selected.size;
  const el = document.getElementById("group-body");
  const cs = selectedCorners();
  if (!cs.length) {
    el.innerHTML = `<p class="small">No corners selected yet.</p>`;
    return;
  }
  const groups = groupByIntersection(cs);
  const packets = [];
  for (let i = 0; i < groups.length; i += MAX_INTERSECTIONS_PER_FORM) packets.push(groups.slice(i, i + MAX_INTERSECTIONS_PER_FORM));
  window._packets = packets.map((p, i) => packetText(p, i + 1, packets.length));

  el.innerHTML = `
    <p><strong>${cs.length} corner${cs.length > 1 ? "s" : ""}</strong> at ${groups.length} intersection${groups.length > 1 ? "s" : ""}:
      ${packets.length} SDOT form${packets.length > 1 ? "s" : ""} (max ${MAX_INTERSECTIONS_PER_FORM} intersections each).</p>
    <div class="buttons">
      <button class="button" data-action="copy-sel-link">Copy link to this selection</button>
      <a class="button" href="${issueUrl(cs)}" target="_blank" rel="noopener">We filed these</a>
    </div>
    <h2>Neighborhood letter</h2>
    <pre class="request" id="letter" tabindex="0" role="region" aria-label="Neighborhood letter">${esc(letterText(cs))}</pre>
    <div class="buttons"><button class="button primary" data-action="copy-letter">Copy letter</button></div>
    <h2>Packets for the SDOT form</h2>
    ${packets.map((p, i) => `
      <div class="packet">
        <h3>Form ${i + 1}: ${MAIN_STREET} & ${p.map(g => esc(baseStreet(g[0]))).join(", ")}</h3>
        <ul>${p.flat().map(c => `<li><button class="link" data-focus="${esc(c.corner_id)}">${esc(CORNER_WORDS[c.corner])} corner, ${esc(baseStreet(c))}</button>
          · ${esc(statusLabel(c)[1].toLowerCase())}</li>`).join("")}</ul>
        <div class="buttons">
          <button class="button primary" data-action="copy-packet" data-i="${i}">Copy packet text</button>
          <a class="button" href="${SDOT_FORM}" target="_blank" rel="noopener">Open SDOT form</a>
        </div>
      </div>`).join("")}`;
}

document.getElementById("pane-group").addEventListener("click", e => {
  const sel = e.target.closest("[data-select]");
  if (sel) {
    const pick = sel.dataset.select;
    const ids = corners.filter(c => (pick === "confirmed" ? c.confirmed_missing : pick === "needs" ? needsWork(c) : false)).map(c => c.corner_id);
    state.selected = new Set(ids);
    refreshMarkers();
    renderGroup();
    renderList();
    writeUrl();
    return;
  }
  const b = e.target.closest("[data-action]");
  if (b?.dataset.action === "copy-letter") copy(letterText(selectedCorners()), "Letter copied");
  if (b?.dataset.action === "copy-packet") copy(window._packets[+b.dataset.i], "Packet copied");
  if (b?.dataset.action === "copy-sel-link") copy(shareUrl({ sel: selParam(state.selected), tab: "group" }), "Link copied");
  const f = e.target.closest("[data-focus]");
  if (f) selectCorner(f.dataset.focus);
});

// On-hold project tip
(() => {
  // Corners where the ramps turn out to be built (checked in person) don't need the project restarted.
  const onHold = corners.filter(c => needsWork(c) && (c.sdot_projects || "").includes("on-hold"));
  if (!onHold.length) return;
  const where = [...new Set(onHold.map(baseStreet))].join(" and ");
  document.getElementById("on-hold-tip").innerHTML =
    `<strong>Ask SDOT to restart stalled work.</strong> Ramps at ${MAIN_STREET} & ${esc(where)} are already in
     ${esc(onHoldText(onHold))} (dashed purple on the map). Asking to un-pause existing work is an easier yes than new work.`;
})();

// ------------------------------------------------------------------ list
function renderList() {
  const el = document.getElementById("corner-list");
  el.innerHTML = groupByIntersection(corners).map(g => `
    <div class="inter">
      <div class="inter-name">${MAIN_STREET} & ${esc(g[0].cross_street)}</div>
      <div class="chips">${g.map(c => `
        <button class="chip ${state.selected.has(c.corner_id) ? "sel" : ""}" data-focus="${esc(c.corner_id)}"
          aria-label="${esc(cornerTitle(c))}: ${esc(statusLabel(c)[1])}">
          ${svgFor(kind(c), ageColor(c.city_install_date), 16, { work: null, checked: !!(checks[c.corner_id] || c.field_date) })}${c.corner}</button>`).join("")}
      </div>
    </div>`).join("");
}
document.getElementById("corner-list").addEventListener("click", e => {
  const f = e.target.closest("[data-focus]");
  if (f) selectCorner(f.dataset.focus);
});

// ------------------------------------------------------------------ key
(() => {
  const counts = { x: 0, partial: 0, ramp: 0, q: 0 };
  corners.forEach(c => counts[kind(c)]++);
  const mid = mix(GREEN, YELLOW, 0.5);
  const li = (svg, text) => `<li>${svg}<span>${text}</span></li>`;
  document.getElementById("key-corners").innerHTML = [
    li(svgFor("x", null, 18), `<strong>No curb ramp</strong>: at least two sources agree (${counts.x})`),
    li(svgFor("partial", mid, 18), `Ramp for <strong>one crossing only</strong> (${counts.partial})`),
    li(svgFor("ramp", mid, 18), `Ramps for both crossings (${counts.ramp})`),
    li(svgFor("q", null, 18), `<strong>Not sure</strong>: one source only, sources disagree, or no data (${counts.q})`),
    li(svgFor("ramp", NO_DATE, 18, { filed: true }), `Green dot: a neighbor has filed a request`),
    li(svgFor("ramp", NO_DATE, 18, { checked: true }), `Orange check: someone looked in person (yours show as you saw them)`),
    li(svgFor("ramp", NO_DATE, 18, { selected: true }), `Blue box: in your group request`),
  ].join("");
  document.getElementById("ramp-bar").style.background =
    `linear-gradient(to right, ${rgb(GREEN)} 0%, ${rgb(GREEN)} ${(30 / 365) * 50}%, ${rgb(YELLOW)} 50%, ${rgb(BROWN)} 100%)`;
  document.getElementById("oldest-year").textContent = oldest ? oldest.slice(0, 4) : "";
  document.getElementById("key-age").innerHTML = li(svgFor("ramp", NO_DATE, 18), "Gray: SDOT has no install date");
  const planned = corners.filter(c => cornerWork(c) === "planned").length;
  const ongoing = corners.filter(c => cornerWork(c) === "ongoing").length;
  document.getElementById("key-work").innerHTML = [
    li(svgFor("q", null, 18, { work: "planned" }), `<strong>Purple dashed ring</strong>: SDOT has open work planned (${planned} corners)`),
    li(svgFor("q", null, 18, { work: "ongoing" }), `<strong>Pink ring</strong>: SDOT work dated this week (${ongoing} corners)`),
  ].join("");
  const f = DATA.fetched || {};
  document.getElementById("data-dates").textContent =
    `Data last refreshed ${(DATA.generated || "").slice(0, 10)}. "This week" means ${new Date(weekStart).toLocaleDateString()} to ${new Date(weekEnd).toLocaleDateString()}.`;
})();

document.querySelector('[data-action="log-request"]').addEventListener("click", e => {
  e.preventDefault();
  const url = issueUrl(state.corner ? [byId.get(state.corner)] : selectedCorners());
  copyIssueBody(url);
  window.open(url, "_blank", "noopener");
});

// ------------------------------------------------------------------ GPS: center on me
// Uses the browser's location only on request. Nothing is stored or sent.
function gpsStop(msg) {
  if (gps.watch != null) navigator.geolocation.clearWatch(gps.watch);
  gps.watch = null;
  gps.following = false;
  gps.layer.clearLayers();
  gps.last = null;
  gps.button.classList.remove("on");
  gps.button.setAttribute("aria-pressed", "false");
  document.getElementById("gps-status").hidden = true;
  if (msg) toast(msg);
  writeUrl();
}

function nearestCorner(lat, lng) {
  let best = null, bestD = Infinity;
  for (const c of corners) {
    const d = map.distance([lat, lng], [c.lat, c.lon]);
    if (d < bestD) { best = c; bestD = d; }
  }
  return [best, bestD];
}

function gpsUpdate(pos) {
  const { latitude: lat, longitude: lng, accuracy } = pos.coords;
  gps.last = { lat, lng, accuracy, at: Date.now() }; // in memory only, for "checked on site"
  gps.layer.clearLayers();
  L.circle([lat, lng], { radius: accuracy, color: "#1a73e8", weight: 1, fillOpacity: 0.12, interactive: false }).addTo(gps.layer);
  L.circleMarker([lat, lng], { radius: 7, color: "#fff", weight: 3, fillColor: "#1a73e8", fillOpacity: 1, interactive: false }).addTo(gps.layer);
  if (gps.following) {
    gps.moving = true;
    map.setView([lat, lng], Math.max(map.getZoom(), 19));
    gps.moving = false;
  }
  const where = document.getElementById("check-where");
  if (where && state.corner) where.innerHTML = whereText(byId.get(state.corner));
  if (where && state.corner && !where.dataset.opened) {
    // Arriving at the open corner opens its report, once.
    const c = byId.get(state.corner);
    if (state.reportOpen == null && reportOpen(c)) { where.dataset.opened = "1"; document.querySelector("#corner-detail [data-report]").open = true; }
  }
  const [c, d] = nearestCorner(lat, lng);
  const el = document.getElementById("gps-status");
  el.hidden = false;
  const feet = d * 3.28084;
  el.innerHTML = feet < 1500
    ? `Nearest corner: <button class="link" data-gps-corner="${esc(c.corner_id)}">${esc(cornerTitle(c))}</button>, about ${Math.round(feet / 10) * 10} ft away` +
      (accuracy > 30 ? ` <span class="small">(location accurate to ~${Math.round(accuracy * 3.28084)} ft)</span>` : "")
    : `You're about ${(d / 1609.34).toFixed(1)} miles from the nearest ${MAIN_STREET} corner on this map.`;
}

gps.layer = L.layerGroup().addTo(map);
const GpsStatus = L.Control.extend({
  options: { position: "bottomleft" },
  onAdd() {
    const el = L.DomUtil.create("div", "gps-status");
    el.id = "gps-status";
    el.hidden = true;
    el.setAttribute("role", "status");
    L.DomEvent.disableClickPropagation(el);
    return el;
  },
});
map.addControl(new GpsStatus());
const GpsControl = L.Control.extend({
  options: { position: "topleft" },
  onAdd() {
    const wrap = L.DomUtil.create("div", "leaflet-bar");
    const b = L.DomUtil.create("a", "gps-button", wrap);
    b.href = "#";
    b.setAttribute("role", "button");
    b.setAttribute("aria-pressed", "false");
    b.title = "Show my location";
    b.setAttribute("aria-label", "Show my location");
    b.innerHTML = `<svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4" fill="currentColor"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><circle cx="12" cy="12" r="7.5" fill="none" stroke="currentColor" stroke-width="2"/></svg>`;
    L.DomEvent.disableClickPropagation(wrap);
    L.DomEvent.on(b, "click", e => {
      L.DomEvent.preventDefault(e);
      if (!("geolocation" in navigator)) return toast("This browser can't share your location");
      if (gps.watch != null && gps.following) return gpsStop("Stopped showing your location");
      if (gps.watch != null) { gps.following = true; b.classList.add("on"); writeUrl(); toast("Following your location"); return; }
      gps.following = true;
      b.classList.add("on");
      b.setAttribute("aria-pressed", "true");
      toast("Finding you…");
      gps.watch = navigator.geolocation.watchPosition(gpsUpdate, err => {
        gpsStop(err.code === err.PERMISSION_DENIED
          ? "Location is blocked. Allow it for this site in your browser settings."
          : "Couldn't get your location. Try again outdoors or with Wi-Fi on.");
      }, { enableHighAccuracy: true, maximumAge: 5000, timeout: 20000 });
    });
    gps.button = b;
    return wrap;
  },
});
map.addControl(new GpsControl());
// Dragging the map yourself stops following (the dot stays). Tap the button to re-center.
map.on("dragstart", () => {
  if (gps.following && !gps.moving) {
    gps.following = false;
    gps.button.classList.remove("on");
    writeUrl();
  }
});
document.addEventListener("click", e => {
  const b = e.target.closest("[data-gps-corner]");
  if (b) {
    gps.following = false;
    gps.button.classList.remove("on");
    selectCorner(b.dataset.gpsCorner);
  }
});

// ------------------------------------------------------------------ boot
renderGroup();
renderList();
renderChecks();
if (state.corner) renderCorner();
showTab(state.tab === "corner" && !state.corner ? "key" : state.tab);
